const extracted = $("Extract Master CV").first().json;
const form = $("Submit External Job").first().json;

const parseJson = (value) => {
  if (typeof value !== "string") return value;
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
};

const unwrapMasterCv = (value) => {
  let current = parseJson(value);

  for (let depth = 0; depth < 5; depth++) {
    if (!current || typeof current !== "object" || Array.isArray(current)) break;
    if (Array.isArray(current.projects)) return current;

    const next =
      current.master_cv ??
      current.cv_json ??
      current.document_data ??
      current.data ??
      current.json;

    if (next === undefined || next === current) break;
    current = parseJson(next);
  }

  return current;
};

const firstValue = (source, names) => {
  for (const name of names) {
    const value = source?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return value;
    }
  }
  return "";
};

const text = (value) => String(value ?? "").trim();
const masterCv = unwrapMasterCv(extracted);

if (!masterCv || typeof masterCv !== "object" || Array.isArray(masterCv)) {
  throw new Error("The master CV file must contain a JSON object.");
}

if (!Array.isArray(masterCv.projects)) {
  throw new Error("The master CV JSON could not be normalized: projects must be an array.");
}

const jobUrl = text(firstValue(form, ["Job URL", "job_url", "jobUrl"]));
if (!jobUrl) throw new Error("Job URL is required.");

const companyName = text(firstValue(form, ["Company Name", "company_name", "companyName"]));
const jobTitle = text(firstValue(form, ["Job Title", "job_title", "jobTitle"]));
const jobDescription = text(firstValue(form, ["Job Description", "job_description", "jobDescription"]));

let parsedUrl;
try {
  parsedUrl = new URL(jobUrl);
} catch {
  throw new Error("Job URL must be a valid URL.");
}

const isLinkedIn =
  parsedUrl.hostname === "linkedin.com" ||
  parsedUrl.hostname.endsWith(".linkedin.com");

const missingCoreFields = !companyName || !jobTitle || !jobDescription;
const needsLinkedInEnrichment = isLinkedIn && missingCoreFields;

if (missingCoreFields && !needsLinkedInEnrichment) {
  throw new Error(
    "For non-LinkedIn jobs, Company Name, Job Title, and Job Description are required."
  );
}

return [
  {
    json: {
      companyName,
      jobTitle,
      jobDescription,
      jobUrl,
      location: text(firstValue(form, ["Location", "location"])),
      contractType: text(firstValue(form, ["Contract Type", "contract_type", "contractType"])),
      publishedAt: text(firstValue(form, ["Published Date", "published_at", "publishedAt"])),
      jobId: text(firstValue(form, ["External Job ID", "job_id", "jobId"])),
      source: needsLinkedInEnrichment ? "LinkedIn URL" : "Manual Form",
      needsLinkedInEnrichment,
      master_cv: masterCv,
    },
  },
];

