const cvContent = $("Create Tailored CV Content").item.json;
const job = cvContent.source_job;

const cvPdf = $("Upload CV PDF to Baserow").first().json;
const cvTex = $("Upload CV TEX to Baserow").first().json;
const coverPdf = $("Upload Cover Letter PDF to Baserow").first().json;
const coverTex = $("Upload Cover Letter TEX to Baserow").first().json;

const requiredUpload = (upload, label) => {
  if (!upload || typeof upload.name !== "string" || !upload.name.trim()) {
    throw new Error(`${label} did not return a valid Baserow user-file name.`);
  }
  return upload;
};

requiredUpload(cvPdf, "CV PDF upload");
requiredUpload(cvTex, "CV TEX upload");
requiredUpload(coverPdf, "Cover letter PDF upload");
requiredUpload(coverTex, "Cover letter TEX upload");

const applicationId = String(cvContent.application_id ?? "application");

const dateValue = job.publishedAt
  ? String(job.publishedAt).slice(0, 10)
  : new Date().toISOString().slice(0, 10);

return [{
  json: {
    "Job ID": String(cvContent.job_id ?? ""),
    "Date": dateValue,
    "Company Name": job.companyName ?? "",
    "Title": job.jobTitle ?? "",
    "Location": job.location ?? "",
    "Job Description": job.jobDescription ?? "",
    "Contract Type": job.contractType ?? "",
    "Cover Letter": [
      {
        "name": coverPdf.name,
        "visible_name": `cover-letter_${applicationId}.pdf`
      },
      {
        "name": coverTex.name,
        "visible_name": `cover-letter_${applicationId}.tex`
      }
    ],
    "CV": [
      {
        "name": cvPdf.name,
        "visible_name": `cv_${applicationId}.pdf`
      },
      {
        "name": cvTex.name,
        "visible_name": `cv_${applicationId}.tex`
      }
    ],
    "Link": job.jobUrl ?? "",
    "Status": "New"
  }
}];

const normalized = $("Normalize Manual Job Input").first().json;
const text = (value) => String(value ?? "").trim();

const firstValue = (source, names) => {
  for (const name of names) {
    const value = source?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return value;
    }
  }
  return "";
};

let scraped = {};

if (normalized.needsLinkedInEnrichment) {
  const response = $input.first().json;
  const rows = Array.isArray(response)
    ? response
    : Array.isArray(response?.data)
      ? response.data
      : Array.isArray(response?.items)
        ? response.items
        : [response];

  scraped = rows.find((row) => row && typeof row === "object" && !row.error) ?? {};

  if (!scraped || Object.keys(scraped).length === 0) {
    throw new Error("The LinkedIn scraper returned no job data.");
  }
}

const companyName =
  text(normalized.companyName) ||
  text(firstValue(scraped, ["companyName", "company", "company_name"]));

const jobTitle =
  text(normalized.jobTitle) ||
  text(firstValue(scraped, ["title", "jobTitle", "job_title"]));

const jobDescription =
  text(normalized.jobDescription) ||
  text(firstValue(scraped, [
    "descriptionText",
    "description",
    "jobDescription",
    "job_description",
  ]));

if (!companyName || !jobTitle || !jobDescription) {
  throw new Error(
    "The LinkedIn job could not be enriched with company name, job title, and full description. Enter the missing fields manually."
  );
}

const scrapedUrl = text(firstValue(scraped, ["jobUrl", "url", "inputUrl"]));
const scrapedJobId = text(firstValue(scraped, ["jobId", "id", "job_id"]));
const urlJobIdMatch = normalized.jobUrl.match(/(?:currentJobId=|\/view\/(?:[^/?#]*-)?)(\d{6,})/);

return [
  {
    json: {
      companyName,
      jobTitle,
      jobDescription,
      jobUrl: text(normalized.jobUrl) || scrapedUrl,
      location:
        text(normalized.location) ||
        text(firstValue(scraped, ["location", "jobLocation"])),
      contractType:
        text(normalized.contractType) ||
        text(firstValue(scraped, ["employmentType", "contractType", "employment_type"])),
      publishedAt:
        text(normalized.publishedAt) ||
        text(firstValue(scraped, ["postedAt", "publishedAt", "postedDate", "published_at"])),
      jobId:
        text(normalized.jobId) ||
        scrapedJobId ||
        text(urlJobIdMatch?.[1]),
      source: normalized.needsLinkedInEnrichment ? "LinkedIn URL" : normalized.source,
      master_cv: normalized.master_cv,
    },
  },
];
